package com.bank.directory;

import java.util.*;
import java.util.logging.*;

public class IdToNameDemo {
    private static final Logger log = Logger.getLogger("Directory");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(101L, "Rajesh"),
            new Employee(102L, "Priya"),
            new Employee(103L, "Amit"));
        DirectoryService service = new DirectoryService();

        Map<Long, String> index = service.idToName(staff);
        log.info(() -> "id 102 → " + index.get(102L));
        log.info(() -> "full index = " + index);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final long id;
    private final String name;
    Employee(long id, String name) { this.id = id; this.name = name; }
    long getId() { return id; }
    String getName() { return name; }
}

// ─── Would be in service/DirectoryService.java ───
class DirectoryService {
    Map<Long, String> idToName(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toMap(
                Employee::getId,     // key: unique id
                Employee::getName)); // value: name
    }
}
